actions.script:
const definition=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition
if (definition.type!=='report' || definition.body.kind!=='playlist') throw new Error('Choose a dashboard playlist')
const at=Number(index || 0),items=definition.body.playlist || []
if (!Number.isInteger(at) || at<0 || at>=items.length) throw new Error('Choose a playlist item')
const id=items[at].definitionId
const output=ec.service.sync().name('org.moqui.report.ReportServices.render#Dashboard').parameters({definitionId:id,from:from || 'now-7d',thru:thru || 'now'}).call()?.dashboard
// a dashboard the viewer may not read: its refusal is the answer
if (!output) throw new Error('This playlist dashboard is not available')
output.definitionId=id;output.absoluteTime=output.range
const frames={};for (const [panelId,panel] of Object.entries(output.panels || {})) frames[panelId]=panel.frames || []
ec.web.sendJsonResponse({dashboard:output,frames})

const definition=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition
if (definition.type!=='report' || definition.body.kind!=='playlist') throw new Error('Choose a dashboard playlist')
playlistTitle=definition.title;playlistSeconds=definition.body.seconds || 30;playlistEntries=[]
// Links still open the full dashboard; the playlist requests authorized frames from its data transition.
const dashboardPath=sri.buildUrl(ec.resource.script('component://tools/template/ReportMount.js').url('dashboard')).path
for (const [index,item] of (definition.body.playlist || []).slice(0,50).entries()) {
    try {
        const dashboard=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId:item.definitionId}).call().definition
        if (dashboard.type==='dashboard') playlistEntries.push({index,title:dashboard.title,url:dashboardPath+'?definitionId='+encodeURIComponent(dashboard.id)+'&from='+encodeURIComponent(from || 'now-7d')+'&thru='+encodeURIComponent(thru || 'now')+'&kiosk=true'})
    } catch (error) { ec.logger.error('Playlist dashboard '+item.definitionId+' unavailable: '+String(error)) }
}
